 function stageMoves(){const st=currentStage();modal(`stage ${st.index+1} · exact thread sequence`, `<p class="modal-copy">The connected chart shows this whole stage. Select a movement below to replay up to that point. Each bead ID refers to one physical bead.</p><div class="v-stage-moves">${st.operations.map((o,i)=>`<button data-stage-move="${i}"><small>${i+1}.</small> ${token(o.id,o.kind)} <span>${o.phase==='position'?'positioning':'weaving'}</span></button>`).join('')}</div>`);document.querySelectorAll('[data-stage-move]').forEach(b=>b.onclick=()=>{state.view='thread';setStageReveal(+b.dataset.stageMove+1);$('modal').close();});}
 function renderStats(){const g=state.model,v=V.validate(g,state.colors,state.palette);state.validation=v;$('vBeadCount').textContent=fmt(g.nodes.length);$('vCubeCount').textContent=g.cubes.length;$('vSize').textContent=g.size.map(x=>(x/10).toFixed(1)).join(' × ');$('vColorCount').textContent=counts().filter(x=>x).length;$('vChecks').textContent=v.valid?`${g.cubes.length} cubes connected by shared faces. ${g.faces.length} closed rings. Every bead is added exactly once.`:v.errors.join(' ');$('vPassNote').textContent=`Size 11/0 · ${state.settings.threadDiameter||.25} mm fishing line. Busiest bead: ${v.maxPasses} planned passes (planning limit ${v.passLimit}); ${v.threadSections} working length${v.threadSections===1?'':'s'}. Finishing and any extra reinforcement need additional hole space. Test with your actual beads.`;const inner=g.nodes.filter(n=>!n.surface).length;$('vInteriorNote').textContent=`The total includes ${inner} interior beads. This is a full cubic RAW structure; the preview hides interior beads unless you choose “Show interior.”`;}
 function renderAll(){renderView();renderPalette();renderGuide();renderStats();window.BeadPartsStudio?.refresh();}
 function setTool(tool){state.tool=tool;$('vRotateTool').classList.toggle('active',tool==='rotate');$('vRotateTool').setAttribute('aria-pressed',tool==='rotate');$('vPaintTool').classList.toggle('active',tool==='paint');$('vPaintTool').setAttribute('aria-pressed',tool==='paint');if(tool==='paint')$('vSelection').textContent=`Painting ${E.code(state.activeColor)} · ${colorName(state.palette[state.activeColor])}. Choose Rotate to turn the model.`;renderView();}
 function selectBead(id,paint=false){const n=state.model.byId.get(id);if(!n)return;state.selected=id;if(paint&&state.colors[n.index]!==state.activeColor){snapshot();state.colors[n.index]=state.activeColor;state.edits=true;renderPalette();renderGuide();renderStats();}const c=state.colors[n.index];$('vSelection').innerHTML=`<b>${id}</b> · ${E.code(c)} ${colorName(state.palette[c])}<br>layer ${state.model.layers.indexOf(n.p[1])+1} · grid ${n.p.join(', ')}<br>first added at ring ${n.addedAt+1} <button class="text-button" id="vGoSelected">show stitch ↗</button>`;$('vGoSelected').onclick=()=>{state.view='step';goStep(n.addedAt);};renderView();}
 function goStep(n){window.BeadJourney?.scheduleSave();state.reveal=Infinity;state.step=E.clamp(Math.round(n),0,state.model.steps.length-1);state.stage=G.atStep(stages(),state.step);state.stageReveal=currentStage().operations.filter(o=>o.step<=state.step).length;state.focusStage=true;renderGuide();if(['step','thread'].includes(state.view)||state.builtOnly)renderView();}
 function goStage(n){state.stage=E.clamp(Math.round(n),0,stages().length-1);const st=currentStage();state.step=st.end;state.reveal=Infinity;state.stageReveal=Infinity;state.focusStage=true;state.view='thread';renderGuide();renderView();$('vViewport').scrollTop=0;}
 function setStageReveal(n){const st=currentStage();state.stageReveal=E.clamp(Math.round(n),0,st.operations.length);const c=G.cursor(st,state.stageReveal);state.step=c.step;state.reveal=c.reveal;state.focusStage=true;if(state.view==='3d')state.view='step';renderGuide();renderView();}
 function setReveal(n){const st=state.model.steps[state.step];state.reveal=E.clamp(n,0,st.travel.length+st.ops.length);state.stage=G.atStep(stages(),state.step);state.stageReveal=currentStage().operations.filter(o=>o.step<state.step).length+state.reveal;state.focusStage=true;renderGuide();renderView();}
 function restoreStage(d){state.model.stages=G.build(state.model);state.stage=G.atStep(stages(),state.step);const st=currentStage();state.stageReveal=st.operations.filter(o=>o.step<state.step).length+Math.min(state.model.steps[state.step].travel.length+state.model.steps[state.step].ops.length,state.reveal);state.focusStage=d.guide?.focused===true;if(d.version===4&&Number.isInteger(d.guide?.stage)&&d.guide.stage>=0&&d.guide.stage<stages().length){state.stage=d.guide.stage;const target=currentStage();state.stageReveal=Number.isInteger(d.guide.reveal)?E.clamp(d.guide.reveal,0,target.operations.length):Infinity;const c=G.cursor(target,Math.min(target.operations.length,state.stageReveal));state.step=c.step;state.reveal=state.stageReveal===Infinity?Infinity:c.reveal;}if(state.view==='layer')state.view='thread';}
 function setView(view){state.view=view;renderView();}
 function changeLayer(n){state.layer=E.clamp(Math.round(n),0,state.model.layers.length-1);renderView();}
 function setMode(next){mode=next;window.BeadformMode=next;$('flatStudio').hidden=next!=='flat';$('volumeStudio').hidden=next!=='volume';$('modeFlat').classList.toggle('active',next==='flat');$('modeFlat').setAttribute('aria-pressed',next==='flat');$('modeVolume').classList.toggle('active',next==='volume');$('modeVolume').setAttribute('aria-pressed',next==='volume');$('dimensionNote').textContent=next==='flat'?'images → flat stitch charts':'your description or image → a whole beaded project';if(next==='volume'&&!state.model)generate(true);}
 function textGuide(){const g=state.model,cc=counts(),codeFor=id=>E.code(state.colors[g.byId.get(id).index]);const lines=[`${state.title} — BEADFORM 3D`,'Original generated construction · cubic right-angle weave',`${g.cubes.length} connected cubes | ${g.nodes.length} unique physical beads | ${g.faces.length} four-bead rings`,`Approximate size: ${g.size.map(v=>(v/10).toFixed(1)).join(' × ')} cm (width × height × depth).`,'','SUPPLIES',`Size 11/0 round (rocaille) seed beads, nominally 2 mm diameter × 1.3 mm along the hole. This project uses a ${state.settings.beadSize} mm diameter estimate.`,`Fishing line: ${state.settings.threadDiameter||.25} mm. Use a needle only if the combined needle and line fit your bead holes.`,`The route has at most ${state.validation.maxPasses} passes per bead, with ${state.validation.threadSections} planned working length(s). The planning limit is a software constraint, NOT a measured hole capacity. Finishing, knots, tails and extra reinforcement are additional. Sample several joined cubes with your actual supplies before making the sculpture.`,'','READING THE DIAGRAMS','Rose curves follow the working ring; green arrows show positioning passes. Strong bead outlines mark new beads. Pale outlines are beads already present. Thread lines run through the hole axes. Optional bead IDs label physical beads, not passage order. Each B ID always means one physical bead, even across different diagrams. The exact movement order is listed below. A star marks a fresh working length; finish its predecessor before starting there. Line crossings between beads are not joins.','The first ring strings four beads and passes through the first again. Secure the start, leaving a tail. For later rings, move through the listed existing beads, then complete each PICK/PASS operation. PICK adds a new bead. PASS traverses a bead already present. Fold faces into a cube; subsequent cubes share a completed face. Coordinates: x right, y up, z front. Interior beads are included in all counts.','If a new working length is marked, secure the previous line at its exit. Anchor the fresh line to the existing thread bridge at the marked start junction beside the indicated bead. Use a secure fishing-line finish you have tested with your supplies. Starting/finishing passes are not invented by this chart.','', 'SHAPE NOTES',state.settings.shape==='custom'?(state.settings.design.kind==='image'?'The reference silhouette defines this shape. Its depth is inflated from the distance to the outline; unseen anatomy is not reconstructed.':state.settings.design.notes||'A model-generated interpretation of the requested subject. Review its proportions and pose.'):'An original example generated from a parametric shape.',`${g.cubes.filter(c=>c.support).length} supporting cells were added to connect thin or diagonally touching details. Cubic RAW approximates curves with steps; tension and needle access need a physical sample.`,'','COLOR KEY (screen colors, not manufacturer codes)',...state.palette.map((h,i)=>`${E.code(i)} ${h.toUpperCase()} ${colorName(h)} — ${cc[i]} beads; prepare ${Math.ceil(cc[i]*1.1)} with 10% spare.`),'','CONSTRUCTION · SIGNIFICANT STAGES'];
   for(const stage of stages()){lines.push('','STAGE '+(stage.index+1)+' — '+stage.label.toUpperCase(),stage.ids.length+' new beads · '+stage.blocks.length+' complete units');for(const st of stage.steps){lines.push('',`${st.index+1}. ${st.label} (${st.faceId}); cube position ${st.position.join(', ')}${st.part?'; part '+st.part:''}`);if(st.threadStart)lines.push(`START THREAD ${st.threadSection||1}: junction ${st.entryCorner||st.start||'first ring'}${st.index?'; beside '+st.anchor:''}.`);if(st.travel.length)lines.push('MOVE THROUGH: '+st.travel.map(id=>`${id} [${codeFor(id)}]`).join(' → '));lines.push(st.ops.map(op=>`${op.kind.toUpperCase()} ${op.id} [${codeFor(op.id)}]`).join(' → '));lines.push(`Ring beads: ${st.ring.join(', ')}. New beads: ${st.ids.length}. Exit junction: ${st.end}.`);if(st.endThread)lines.push('Secure this working length at its exit.');}}
   lines.push('','FINISH','Check that every cube has six closed faces. Secure every thread end with your tested fishing-line finish. Only add reinforcement if the actual holes have space. Findings, hanging loops, needles, and additional finishing beads are separate.','','DESIGN NOTES','All generated diagrams and instructions are original to this app. The uploaded example informed drawing conventions only; its bead layout and instructions were not copied. Digital checks cover topology, inventory, route continuity and planned passage limits. They do not establish physical tension, needle access, hole fit or exact likeness.','Generic technique: https://www.firemountaingems.com/learn/categories/jewelry-medium/bead-stringing/how-tos-on-bead-stringing/J343-project-tutorial.html');return lines.join('\n');
 }
 function beadCSV(){const g=state.model;return '\ufeffBead ID,Grid X,Grid Y,Grid Z,Layer,Hole axis,Surface,Added at ring,Symbol,Hex\r\n'+g.nodes.map(n=>[n.id,...n.p,g.layers.indexOf(n.p[1])+1,['X','Y','Z'][n.axis],n.surface?'yes':'no',n.addedAt+1,E.code(state.colors[n.index]),state.palette[state.colors[n.index]]].join(',')).join('\r\n');}
