 function slug(){return (state.title||'beadform-3d').normalize('NFKD').replace(/[^a-zA-Z0-9 _-]/g,'').trim().replace(/\s+/g,'-').slice(0,65)||'beadform-3d';}
 function download(content,type,suffix){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=slug()+suffix;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Your 3D pattern download is ready.');}
 function project(){return {makerProgress:state.makerProgress||null,finishedBuild:window.BeadJourney?.getBuild()||null,partsGuide:{version:11,stage:state.partsStage||0,reveal:Number.isFinite(state.partsReveal)?state.partsReveal:null},construction:state.construction||'parts',format:'beadform-project',version:4,dimension:'volume',title:state.title,settings:{...state.settings},sourceName:state.sourceName,sourceData:state.sourceData,palette:state.palette.slice(),colors:state.colors.slice(),step:state.step,layer:state.layer,manualEdits:state.edits,guide:{stage:state.stage,reveal:Number.isFinite(state.stageReveal)?state.stageReveal:null,focused:state.focusStage},creation:{prompt:document.getElementById('vPrompt').value,inputMode:state.inputMode||'text'},reveal:Number.isFinite(state.reveal)?state.reveal:null,view:{yaw:state.yaw,pitch:state.pitch,mode:state.view}};}
